import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cap = int(data[1])
    items = []
    for i in range(n):
        items.append((int(data[2 + 2 * i]), int(data[3 + 2 * i])))
    answer = 0
    for mask in range(1 << n):
        total_w = 0
        total_v = 0
        for i in range(n):
            if mask >> i & 1:
                total_w += items[i][0]
                total_v += items[i][1]
        if total_w <= cap and total_v > answer:
            answer = total_v
    print(answer)


main()
